custom_fields.infos:
[[[
  const maintenant = new Date();

  const heure = maintenant.toLocaleTimeString('fr-FR', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });

  /* ==============================
     VOLETS
     ============================== */
  const volets = Object.values(states).filter((e) => {
    if (!e.entity_id.startsWith('cover.')) return false;
    const id = e.entity_id.toLowerCase();
    const nom = String(e.attributes?.friendly_name || '').toLowerCase();
    return (
      id.includes('volet') ||
      id.startsWith('cover.rfy_') ||
      nom.includes('volet') ||
      nom.startsWith('rfy ')
    );
  });

  const voletsConnus = volets.filter((e) => !['unknown', 'unavailable'].includes(e.state));
  const voletsOuverts = voletsConnus.filter((e) => e.state !== 'closed');

  let texteVolets;
  let couleurVolets = 'vert';

  if (voletsConnus.length === 0) {
    texteVolets = 'Volets : état indisponible';
    couleurVolets = 'orange';
  } else if (voletsOuverts.length === 0) {
    texteVolets = 'Tous les volets sont fermés';
    couleurVolets = 'vert';
  } else if (voletsOuverts.length === 1) {
    texteVolets = '1 volet est ouvert';
    couleurVolets = 'orange';
  } else {
    texteVolets = `${voletsOuverts.length} volets sont ouverts`;
    couleurVolets = 'orange';
  }

  /* ==============================
     LUMIÈRES
     ============================== */
  const lumieres = Object.values(states).filter((e) => e.entity_id.startsWith('light.'));
  const lumieresAllumees = lumieres.filter((e) => e.state === 'on');

  let texteLumieres;
  let couleurLumieres;

  if (lumieresAllumees.length === 0) {
    texteLumieres = 'Aucune lumière oubliée';
    couleurLumieres = 'vert';
  } else if (lumieresAllumees.length === 1) {
    texteLumieres = '1 lumière est allumée';
    couleurLumieres = 'jaune';
  } else {
    texteLumieres = `${lumieresAllumees.length} lumières sont allumées`;
    couleurLumieres = 'jaune';
  }

  /* ==============================
     TEMPÉRATURE (CAPTEUR SALON DIRECT)
     ============================== */
  const salonTemp = Object.values(states).find(e => e.entity_id === 'sensor.salon_capteur_temperature_temperature');
  const weatherEntity = Object.values(states).find((e) => e.entity_id.startsWith('weather.'));

  let texteTemperature = 'Température : N/A';

  if (salonTemp && salonTemp.state && !['unknown', 'unavailable', 'none'].includes(salonTemp.state.toLowerCase())) {
    const valTemp = parseFloat(salonTemp.state).toFixed(1).replace('.', ',');
    texteTemperature = `Température intérieure : ${valTemp} °C`;
  } else if (weatherEntity && weatherEntity.attributes?.temperature !== undefined) {
    texteTemperature = `Température extérieure : ${weatherEntity.attributes.temperature} °C`;
  }

  /* ==============================
     AGENDA
     ============================== */
  const calendrier = states['calendar.famille_blaise'];
  let texteAgenda = 'Prochain rendez-vous : aucun';
  let couleurAgenda = 'violet';

  if (calendrier) {
    const message = calendrier.attributes?.message;
    const debut = calendrier.attributes?.start_time;

    if (message) {
      let dateAgenda = '';
      if (debut) {
        const d = new Date(debut);
        if (!isNaN(d.getTime())) {
          dateAgenda = d.toLocaleDateString('fr-FR', {
            day: '2-digit',
            month: 'short'
          });
        }
      }
      texteAgenda = dateAgenda ? `${message} · ${dateAgenda}` : message;
    }
  }

  /* ==============================
     TEMPO
     ============================== */
  const tempoEntity = states['sensor.rte_tempo_couleur_actuelle'];
  const tempoBrut = tempoEntity?.state || 'Inconnu';

  const normaliseTempo = (value) => {
    const v = String(value).toLowerCase().trim();
    if (v.includes('bleu') || v === 'blue') return 'Bleu';
    if (v.includes('blanc') || v === 'white') return 'Blanc';
    if (v.includes('rouge') || v === 'red') return 'Rouge';
    return value;
  };

  const tempo = normaliseTempo(tempoBrut);
  let couleurTempo = 'cyan';
  if (tempo === 'Rouge') couleurTempo = 'rouge';
  if (tempo === 'Blanc') couleurTempo = 'blanc';

  /* ==============================
     SPA
     ============================== */
  const spa = states['switch.disjoncteur_spa_interrupteur'];
  let texteSpa = 'Spa : indisponible';
  let couleurSpa = 'orange';

  if (spa) {
    if (spa.state === 'on') {
      texteSpa = 'Spa : alimenté';
      couleurSpa = 'vert';
    } else if (spa.state === 'off') {
      texteSpa = 'Spa : coupé';
      couleurSpa = 'orange';
    }
  }

  /* ==============================
     CONSOMMATION EDF
     ============================== */
  const linky = states['sensor.linky_19446454395641_consumption'];
  let texteEDF = 'Consommation EDF : indisponible';
  let couleurEDF = 'orange';

  if (linky && !['unknown', 'unavailable'].includes(linky.state)) {
    const valeur = Number(linky.state);
    if (!isNaN(valeur)) {
      const conso = valeur.toFixed(1).replace('.', ',');
      texteEDF = `Consommation hier : ${conso} kWh`;
      couleurEDF = 'vert';
    }
  }

  /* ==============================
     AFFICHAGE
     ============================== */
  return `
    <div class="cassandra-infos">
      <div class="cassandra-titre">✦ CASSANDRA</div>
      <div class="cassandra-bonjour">Bonjour Johnatan ! 👋</div>
      <div class="cassandra-lignes">
        <div class="cassandra-ligne">
          <span class="point ${couleurVolets}"></span>
          <span>${texteVolets}</span>
        </div>
        <div class="cassandra-ligne">
          <span class="point ${couleurLumieres}"></span>
          <span>${texteLumieres}</span>
        </div>
        <div class="cassandra-ligne">
          <span class="point bleu"></span>
          <span>${texteTemperature}</span>
        </div>
        <div class="cassandra-ligne">
          <span class="point ${couleurAgenda}"></span>
          <span>${texteAgenda}</span>
        </div>
        <div class="cassandra-ligne">
          <span class="point ${couleurTempo}"></span>
          <span>Tempo : ${tempo}</span>
        </div>
        <div class="cassandra-ligne">
          <span class="point ${couleurSpa}"></span>
          <span>${texteSpa}</span>
        </div>
        <div class="cassandra-ligne">
          <span class="point ${couleurEDF}"></span>
          <span>${texteEDF}</span>
        </div>
      </div>
      <div class="cassandra-maj">
        Dernière mise à jour : ${heure}
      </div>
    </div>
  `;
]]]

custom_fields.heure:
[[[
  const maintenant = new Date();

  const heure = maintenant.toLocaleTimeString('fr-FR', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });

  let jour = maintenant.toLocaleDateString('fr-FR', {
    weekday: 'long'
  });
  jour = jour.charAt(0).toUpperCase() + jour.slice(1);

  const date = maintenant.toLocaleDateString('fr-FR', {
    day: 'numeric',
    month: 'long',
    year: 'numeric'
  });

  return `
    <div class="cassandra-horloge">
      <div class="cassandra-heure">${heure}</div>
      <div class="cassandra-jour">${jour}</div>
      <div class="cassandra-date">${date}</div>
    </div>
  `;
]]]

