custom_fields.contenu:
[[[
  const weather = states['weather.forecast_maison'];
  const forecastSensor = states['sensor.previsions_meteo_maison'];

  const temperature =
    weather?.attributes?.temperature ?? '--';

  const condition =
    weather?.state ?? 'partlycloudy';

  const forecasts =
    forecastSensor?.attributes?.forecast ?? [];

  const icons = {
    'clear-night': '🌙',
    sunny: '☀️',
    partlycloudy: '🌤️',
    cloudy: '☁️',
    rainy: '🌧️',
    pouring: '🌧️',
    lightning: '⛈️',
    'lightning-rainy': '⛈️',
    snowy: '🌨️',
    'snowy-rainy': '🌨️',
    fog: '🌫️',
    windy: '💨',
    'windy-variant': '💨',
    hail: '🌨️',
    exceptional: '⚠️'
  };

  const descriptions = {
    'clear-night': 'Nuit dégagée',
    sunny: 'Ensoleillé',
    partlycloudy: 'Partiellement nuageux',
    cloudy: 'Nuageux',
    rainy: 'Pluvieux',
    pouring: 'Fortes pluies',
    lightning: 'Orageux',
    'lightning-rainy': 'Orage et pluie',
    snowy: 'Neige',
    'snowy-rainy': 'Neige et pluie',
    fog: 'Brouillard',
    windy: 'Venteux',
    'windy-variant': 'Venteux',
    hail: 'Grêle',
    exceptional: 'Conditions exceptionnelles'
  };

  const labels = [
    'AUJ.',
    'DEM.',
    'J+2',
    'J+3',
    'J+4'
  ];

  const formatTemp = (value) => {
    if (value === undefined || value === null) return '--';

    const n = Number(value);

    if (Number.isNaN(n)) return '--';

    return Number.isInteger(n)
      ? n.toString()
      : n.toFixed(1).replace('.', ',');
  };

  const forecastHtml =
    Array.from({ length: 5 }, (_, index) => {

      const item = forecasts[index];

      if (!item) {
        return `
          <div class="jour">
            <div class="label">${labels[index]}</div>
            <div class="forecast-icon">🌤️</div>
            <div class="max">--°</div>
            <div class="min">--°</div>
          </div>
        `;
      }

      const itemCondition =
        item.condition ?? 'partlycloudy';

      return `
        <div class="jour">

          <div class="label">
            ${labels[index]}
          </div>

          <div class="forecast-icon">
            ${icons[itemCondition] ?? '🌤️'}
          </div>

          <div class="max">
            ${formatTemp(item.temperature)}°
          </div>

          <div class="min">
            ${formatTemp(item.templow)}°
          </div>

        </div>
      `;
    }).join('');

  return `
    <div class="meteo-v7">

      <div class="haut">

        <div class="icone-principale">
          ${icons[condition] ?? '🌤️'}
        </div>

        <div class="infos">

          <div class="titre">
            Météo Maison Blaise
          </div>

          <div class="temperature">
            ${formatTemp(temperature)}°C
          </div>

          <div class="condition">
            ${descriptions[condition] ?? condition}
          </div>

        </div>

      </div>

      <div class="separateur"></div>

      <div class="previsions">
        ${forecastHtml}
      </div>

    </div>
  `;
]]]

