custom_fields.info:
[[[
  // =========================
  // VOLETS
  // =========================
  const volets = [
    'cover.rfy_010003_1',
    'cover.rfy_010004_1',
    'cover.rfy_010005_1',
    'cover.rfy_010006_1',
    'cover.rfy_010007_1',
    'cover.volet_chambre_parents'
  ];

  const voletsOuverts = volets.filter(e =>
    states[e] &&
    states[e].state !== 'closed'
  ).length;

  const voletsOK = voletsOuverts === 0;

  // =========================
  // LUMIERES
  // =========================
  const lumieres = [
    'light.pool_house',
    'light.pool_house_2',
    'light.pool_house_3',
    'light.spa',
    'light.spot_palmier',
    'light.spot_spa_01',
    'light.spot_spa_02',
    'light.spot_spa_03',
    'light.spot_terrasse_01',
    'light.spot_terrasse_02',
    'light.spot_terrasse_03',
    'light.spot_terrasse_04',
    'light.terrasse'
  ];

  const lumieresAllumees = lumieres.filter(e =>
    states[e] &&
    states[e].state === 'on'
  ).length;

  const lumieresOK = lumieresAllumees === 0;

  // =========================
  // CLIMATISATION
  // =========================
  const clim = states['climate.climatisation_salon_mqtt_hvac'];
  let climTexte = 'Éteinte';
  let climClass = 'ok';
  let climCouleur = 'green';

  if (clim) {
    if (['unavailable', 'unknown'].includes(clim.state)) {
      climTexte = 'Indisponible';
      climClass = 'warning';
      climCouleur = 'orange';
    } else if (clim.state === 'off') {
      climTexte = 'Éteinte';
      climClass = 'off';
      climCouleur = 'green';
    } else {
      const modes_fr = { cool: 'Froid', heat: 'Chaud', heat_cool: 'Auto', fan_only: 'Ventil.', dry: 'Déshum.' };
      const modeLabel = modes_fr[clim.state] || clim.state;
      const targetTemp = clim.attributes?.temperature ? ` ${clim.attributes.temperature}°` : '';
      climTexte = `${modeLabel}${targetTemp}`;
      climClass = 'ok';
      climCouleur = 'blue';
    }
  }

  // =========================
  // SPA
  // =========================
  const spa = states['switch.disjoncteur_spa_interrupteur'];

  let spaTexte = 'Indisponible';
  let spaClass = 'warning';

  if (spa) {
    if (spa.state === 'on') {
      spaTexte = 'Allumé';
      spaClass = 'ok';
    } else if (spa.state === 'off') {
      spaTexte = 'Éteint';
      spaClass = 'off';
    }
  }

  return `
    <div class="health-card">

      <div class="header">
        <div class="header-left">
          <ha-icon icon="mdi:home-heart"></ha-icon>
          <span>Santé de la maison</span>
        </div>
        <div class="global-dot"></div>
      </div>

      <div class="separator"></div>

      <div class="ligne">
        <div class="gauche">
          <div class="status ${voletsOK ? 'ok' : 'warning'}">
            ${voletsOK ? '✓' : '!'}
          </div>
          <span class="label">Volets</span>
        </div>

        <span class="value ${voletsOK ? 'green' : 'orange'}">
          ${voletsOK ? 'OK' : voletsOuverts + ' ouvert' + (voletsOuverts > 1 ? 's' : '')}
        </span>
      </div>

      <div class="ligne">
        <div class="gauche">
          <div class="status ${lumieresOK ? 'ok' : 'warning'}">
            ${lumieresOK ? '✓' : '!'}
          </div>
          <span class="label">Lumières</span>
        </div>

        <span class="value ${lumieresOK ? 'green' : 'orange'}">
          ${lumieresOK ? 'OK' : lumieresAllumees + ' allumée' + (lumieresAllumees > 1 ? 's' : '')}
        </span>
      </div>

      <div class="ligne">
        <div class="gauche">
          <div class="status ${climClass}">
            ${climClass === 'warning' ? '!' : '✓'}
          </div>
          <span class="label">Climatisation</span>
        </div>
        <span class="value ${climCouleur}">
          ${climTexte}
        </span>
      </div>

      <div class="ligne">
        <div class="gauche">
          <div class="status ${spaClass}">
            ${spaClass === 'warning' ? '!' : '✓'}
          </div>
          <span class="label">Spa</span>
        </div>

        <span class="value ${spaClass === 'warning' ? 'orange' : 'green'}">
          ${spaTexte}
        </span>
      </div>

      <div class="ligne">
        <div class="gauche">
          <div class="status pending">•</div>
          <span class="label">Caméras</span>
        </div>
        <span class="value blue">À raccorder</span>
      </div>

    </div>
  `;
]]]

