custom_fields.contenu:
[[[
  const e = states['media_player.spotify_john'];

  const state = e?.state || 'unknown';

  const titre =
    e?.attributes?.media_title ||
    'Aucune lecture';

  const artiste =
    e?.attributes?.media_artist ||
    'Spotify';

  const pochette =
    e?.attributes?.entity_picture || '';

  const lecture =
    state === 'playing';

  const statut =
    lecture
      ? 'Lecture en cours'
      : state === 'paused'
        ? 'En pause'
        : state === 'idle'
          ? 'Prêt'
          : 'Indisponible';

  return `
    <div class="ambiance-card">

      <div class="header">

        <div>
          <div class="titre">
            Ambiance Spotify
          </div>

          <div class="statut">
            ${statut}
          </div>
        </div>

        <div class="spotify-icon">
          <ha-icon icon="mdi:spotify"></ha-icon>
        </div>

      </div>

      <div class="media-zone">

        <div
          class="cover"
          style="
            background-image:
            ${pochette
              ? `url('${pochette}')`
              : `linear-gradient(
                  145deg,
                  rgba(30,215,96,0.16),
                  rgba(15,23,42,0.95)
                )`
            };
          "
        >
          ${!pochette
            ? `<ha-icon icon="mdi:music-note"></ha-icon>`
            : ''
          }
        </div>

        <div class="media-info">

          <div class="track">
            ${titre}
          </div>

          <div class="artist">
            ${artiste}
          </div>

        </div>

      </div>

    </div>
  `;
]]]

