custom_fields.contenu:
[[[
  const cal = states['calendar.famille_blaise'];

  const message =
    cal?.attributes?.message ||
    'Aucun événement à venir';

  const start =
    cal?.attributes?.start_time || null;

  const allDay =
    cal?.attributes?.all_day === true;

  let jour = '--';
  let mois = '---';
  let heure = '';
  let info = 'Aucun horaire';

  if (start) {
    const d = new Date(start);

    if (!isNaN(d.getTime())) {

      jour = d.toLocaleDateString('fr-FR', {
        day: '2-digit'
      });

      mois = d.toLocaleDateString('fr-FR', {
        month: 'short'
      }).replace('.', '').toUpperCase();

      if (allDay) {
        info = 'Journée entière';
      } else {
        heure = d.toLocaleTimeString('fr-FR', {
          hour: '2-digit',
          minute: '2-digit'
        });

        info = heure;
      }
    }
  }

  return `
    <div class="agenda-card">

      <div class="agenda-header">

        <div>
          <div class="agenda-title">
            Agenda
          </div>

          <div class="agenda-subtitle">
            Famille Blaise
          </div>
        </div>

        <div class="agenda-icon">
          <ha-icon icon="mdi:calendar-month"></ha-icon>
        </div>

      </div>

      <div class="agenda-separator"></div>

      <div class="agenda-main">

        <div class="date-box">
          <div class="date-day">
            ${jour}
          </div>

          <div class="date-month">
            ${mois}
          </div>
        </div>

        <div class="event-box">

          <div class="event-small">
            Prochain événement
          </div>

          <div class="event-title">
            ${message}
          </div>

        </div>

      </div>

      <div class="event-meta">

        <ha-icon icon="${allDay ? 'mdi:calendar-blank' : 'mdi:clock-outline'}"></ha-icon>

        <span>
          ${info}
        </span>

      </div>

      <div class="agenda-footer">
        <span>Voir l’agenda complet</span>
        <ha-icon icon="mdi:chevron-right"></ha-icon>
      </div>

    </div>
  `;
]]]

