custom_fields.titre:
[[[
  const lockState = hass.states[variables.lock]?.state;
  const ev = hass.states[variables.doorbell];

  const derniere = ev && ev.state !== 'unavailable'
    ? new Date(ev.last_changed).getTime()
    : 0;

  const sonne = (Date.now() - derniere) < 30000;
  const ouverte = lockState === 'unlocked';

  let statut = 'Entrée en direct';
  let couleur = '#28e987';
  let icone = 'mdi:doorbell';

  if (sonne) {
    statut = 'QUELQU’UN SONNE !';
    couleur = '#ffb020';
    icone = 'mdi:bell-ring';
  } else if (ouverte) {
    statut = 'PORTILLON OUVERT';
    couleur = '#28e987';
    icone = 'mdi:door-open';
  }

  return `
    <div class="camera-header ${sonne ? 'header-sonne' : ''}">

      <div>
        <div class="camera-titre">
          Visiophone
        </div>

        <div
          class="camera-statut"
          style="color:${couleur}"
        >
          <span
            class="camera-point"
            style="
              background:${couleur};
              box-shadow:0 0 8px ${couleur};
            "
          ></span>

          ${statut}
        </div>
      </div>

      <div
        class="camera-icon"
        style="
          background:rgba(41,198,255,0.11);
        "
      >
        <ha-icon
          icon="${icone}"
          style="color:${couleur}"
        ></ha-icon>
      </div>

    </div>
  `;
]]]

