[[[
  const e = states['sensor.linky_19446454395641_consumption'];

  if (!e) {
    return `
      <div class="energie-v7">
        <div class="erreur">Capteur Linky indisponible</div>
      </div>
    `;
  }

  const state = parseFloat(e.state);

  const hier = isNaN(state)
    ? '--'
    : state.toFixed(1).replace('.', ',');

  const semaine = e.attributes.current_week !== undefined
    ? Number(e.attributes.current_week).toFixed(1).replace('.', ',')
    : '--';

  const semaineDerniere = e.attributes.last_week !== undefined
    ? Number(e.attributes.last_week).toFixed(1).replace('.', ',')
    : '--';

  const mois = e.attributes.current_month !== undefined
    ? Number(e.attributes.current_month).toFixed(1).replace('.', ',')
    : '--';

  const tempoActuel =
    states['sensor.rte_tempo_couleur_actuelle'];

  const tempoDemain =
    states['sensor.rte_tempo_prochaine_couleur'];

  const heuresCreuses =
    states['binary_sensor.rte_tempo_heures_creuses'];

  const joursBleus =
    states['sensor.rte_tempo_cycle_jours_restants_bleu'];

  const joursBlancs =
    states['sensor.rte_tempo_cycle_jours_restants_blanc'];

  const joursRouges =
    states['sensor.rte_tempo_cycle_jours_restants_rouge'];

  const couleurAujourdHui =
    tempoActuel ? tempoActuel.state : 'Inconnu';

  const couleurDemain =
    tempoDemain ? tempoDemain.state : 'Inconnu';

  const normaliseCouleur = (value) => {
    const v = String(value || '').toLowerCase().trim();

    if (v.includes('bleu') || v === 'blue') return 'Bleu';
    if (v.includes('blanc') || v === 'white') return 'Blanc';
    if (v.includes('rouge') || v === 'red') return 'Rouge';

    return '--';
  };

  const tempoColor = (value) => {
    const v = String(value || '').toLowerCase().trim();

    if (v.includes('bleu') || v === 'blue') return '#3f8cff';
    if (v.includes('blanc') || v === 'white') return '#f4f4f5';
    if (v.includes('rouge') || v === 'red') return '#ff4d67';

    return '#81909d';
  };

  const todayName =
    normaliseCouleur(couleurAujourdHui);

  const tomorrowName =
    normaliseCouleur(couleurDemain);

  const cToday =
    tempoColor(couleurAujourdHui);

  const cTomorrow =
    tempoColor(couleurDemain);

  const tarif =
    heuresCreuses &&
    heuresCreuses.state === 'on'
      ? 'HC'
      : 'HP';

  const safeState = (entity) => {
    if (!entity) return '--';

    if (
      ['unknown', 'unavailable']
        .includes(entity.state)
    ) {
      return '--';
    }

    return entity.state;
  };

  const joursB = safeState(joursBleus);
  const joursW = safeState(joursBlancs);
  const joursR = safeState(joursRouges);

  const blueHC =
    Number(states['sensor.edf_tempo_price_blue_hc']?.state);

  const blueHP =
    Number(states['sensor.edf_tempo_price_blue_hp']?.state);

  const whiteHC =
    Number(states['sensor.edf_tempo_price_white_hc']?.state);

  const whiteHP =
    Number(states['sensor.edf_tempo_price_white_hp']?.state);

  const redHC =
    Number(states['sensor.edf_tempo_price_red_hc']?.state);

  const redHP =
    Number(states['sensor.edf_tempo_price_red_hp']?.state);

  let prixHC = blueHC;
  let prixHP = blueHP;

  const couleurPrix =
    String(couleurAujourdHui).toLowerCase();

  if (
    couleurPrix.includes('blanc') ||
    couleurPrix === 'white'
  ) {
    prixHC = whiteHC;
    prixHP = whiteHP;
  }

  if (
    couleurPrix.includes('rouge') ||
    couleurPrix === 'red'
  ) {
    prixHC = redHC;
    prixHP = redHP;
  }

  const prixMoyen =
    (!isNaN(prixHC) && !isNaN(prixHP))
      ? ((prixHC * 8) + (prixHP * 16)) / 24
      : NaN;

  const cout =
    !isNaN(state) && !isNaN(prixMoyen)
      ? (state * prixMoyen)
          .toFixed(2)
          .replace('.', ',')
      : '--';

  return `

    <div class="energie-v7">

      <div class="header">

        <div>
          <div class="titre">
            Énergie
          </div>

          <div class="status">
            <span class="status-dot"></span>
            Linky connecté
          </div>
        </div>

        <div class="header-icon">
          <ha-icon icon="mdi:lightning-bolt"></ha-icon>
        </div>

      </div>


      <div class="principal">

        <div class="conso">

          <div class="label">
            Consommation hier
          </div>

          <div class="conso-value">
            ${hier}
            <span>kWh</span>
          </div>

        </div>


        <div class="wallet">
          <ha-icon icon="mdi:wallet-outline"></ha-icon>
        </div>


        <div class="cout">

          <div class="label">
            Coût hier
          </div>

          <div class="cout-value">
            ${cout} €
          </div>

        </div>

      </div>


      <div class="tempo">

        <div class="tempo-title">
          TEMPO
        </div>

        <div class="tempo-day">

          <span
            class="dot"
            style="
              background:${cToday};
              box-shadow:0 0 7px ${cToday};
            ">
          </span>

          <div>
            <small>Auj.</small>
            <strong>${todayName}</strong>
          </div>

        </div>

        <div class="arrow">
          →
        </div>

        <div class="tempo-day">

          <span
            class="dot"
            style="
              background:${cTomorrow};
              box-shadow:0 0 7px ${cTomorrow};
            ">
          </span>

          <div>
            <small>Dem.</small>
            <strong>${tomorrowName}</strong>
          </div>

        </div>

        <div class="tarif">

          <small>Tarif</small>

          <strong>
            ${tarif}
          </strong>

        </div>

        <div class="days">

          <div class="day blue">
            <b>B</b>
            <span>${joursB}</span>
          </div>

          <div class="day white">
            <b>W</b>
            <span>${joursW}</span>
          </div>

          <div class="day red">
            <b>R</b>
            <span>${joursR}</span>
          </div>

        </div>

      </div>


      <div class="stats">

        <div class="stat">

          <div class="stat-icon blue-icon">
            <ha-icon icon="mdi:calendar-week"></ha-icon>
          </div>

          <div class="stat-text">

            <span>
              Sem. en cours
            </span>

            <strong>
              ${semaine}
              <small>kWh</small>
            </strong>

          </div>

        </div>


        <div class="stat">

          <div class="stat-icon purple-icon">
            <ha-icon icon="mdi:calendar-arrow-left"></ha-icon>
          </div>

          <div class="stat-text">

            <span>
              Sem. dernière
            </span>

            <strong>
              ${semaineDerniere}
              <small>kWh</small>
            </strong>

          </div>

        </div>


        <div class="stat">

          <div class="stat-icon green-icon">
            <ha-icon icon="mdi:calendar-month"></ha-icon>
          </div>

          <div class="stat-text">

            <span>
              Ce mois
            </span>

            <strong>
              ${mois}
              <small>kWh</small>
            </strong>

          </div>

        </div>

      </div>

    </div>
  `;
]]]

