custom_fields.sonnerie:
[[[
  const ev = hass.states[variables.doorbell];

  const derniere = ev && ev.state !== 'unavailable'
    ? new Date(ev.last_changed).getTime()
    : 0;

  const active = (Date.now() - derniere) < 30000;

  if (active) {
    return `
      <div class="ring-badge ring-active">

        <ha-icon icon="mdi:bell-ring"></ha-icon>

        <span>
          QUELQU'UN SONNE !
        </span>

      </div>
    `;
  }

  return `
    <div class="ring-badge">

      <ha-icon icon="mdi:shield-check-outline"></ha-icon>

      <span>
        Surveillance active
      </span>

    </div>
  `;
]]]

