  font-size: 17px;

  font-weight: 700;
}


.camera-statut {

  margin-top: 6px;

  display: flex;

  align-items: center;

  gap: 6px;

  font-size: 10px;

  font-weight: 700;
}


.camera-point {

  width: 6px;
  height: 6px;

  flex: 0 0 6px;

  border-radius: 50%;
}


.camera-icon {

  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 13px;

  box-shadow:
    0 0 14px rgba(41,198,255,0.22);
}


.camera-icon ha-icon {

  width: 22px;
  height: 22px;
}


/* =========================
   SONNERIE
   ========================= */

.ring-badge {

  height: 100%;

  display: flex;

  align-items: center;

  gap: 6px;

  font-size: 9px;

  font-weight: 700;

  letter-spacing: 0.6px;

  color:
    rgba(140,160,175,0.8);
}


.ring-badge ha-icon {

  width: 13px;
  height: 13px;
}


.ring-badge.ring-active {

  color: #ffb020;

  animation:
    ring-pulse 1s ease-in-out infinite;
}


.ring-badge.ring-active ha-icon {

  color: #ffb020;

  filter:
    drop-shadow(0 0 5px rgba(255,176,32,0.9));
}


@keyframes ring-pulse {

  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.35;
  }

}
